# Load all grids from session logs
import os, glob, re

def load():
    d = os.environ.get('RLM_SESSION_DIR', '')
    if not d:
        return {}

    # Find session log file
    session_file = os.path.join(d, '../../sessions/', os.path.basename(d) + '.jsonl')
    if not os.path.exists(session_file):
        return {}

    text = open(session_file).read()
    G = {}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', text):
        k, h, w = m[1], int(m[2]), int(m[3])
        # Parse the grid after the marker
        rest = text[m.end():].split('\n')[:h]
        rows = []
        valid = True
        for r in rest:
            if r.strip() and not all(x.isdigit() for x in r.split()):
                valid = False
            rows.append([int(x) for x in r.split()])
        if valid and rows:
            G[k] = [[int(x) for x in r.split()] for r in rows]
    return G

G = load()
print("Grids loaded:", sorted(G.keys()))
for k in sorted(G.keys()):
    print(f"\n{k}: {G[k]}")

